(function(){const RA=globalThis.RA,D=(l,p)=>RA.D(l,p),E=(origin,prefix,root,suffix,source)=>({origin,prefix,root,suffix,source}),C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:"authored"}),M=(errorType,wrong,right,reason)=>({errorType,wrong,right,reason}),Q=(id,senseId,type,prompt,options,answer,explain,errorType)=>({id,senseId,type,prompt,options,answer,explain,errorType});
D("pronounce",{etymology:E("From Old French prononcier and Late Latin pronunciare, from Latin pronuntiare ‘announce, proclaim, utter’, built from pro ‘forth, publicly’ and nuntiare ‘announce’. The speech-sound sense is one later development.","pro-","nuntiare",null,"Etymonline, pronounce (https://www.etymonline.com/word/pronounce)."),contexts:[C("pronounce.s1","語言","The guest asked the host how to pronounce the village name before introducing the award winner.","嘉賓在介紹得獎者前，先詢問主持人村名該怎麼發音。","To pronounce a word or name is to produce its spoken sounds.","Pronounce takes the village name as its object; how asks about the manner of saying it.","The guest wants the correct spoken form of the name.") ,C("pronounce.s2","法律","After hearing both sides, the judge pronounced the defendant not guilty in open court.","聽取雙方陳述後，法官在公開法庭宣判被告無罪。","To pronounce can mean state a decision or judgment formally.","Pronounced takes the defendant as object and not guilty as the complement describing the ruling.","The judge formally declares the court's decision.")],mistakes:[M("collocation","How do you pronounce for this family name?","How do you pronounce this family name?","In the speech sense, pronounce takes the word or name directly as its object; for is not used before it here.")],quiz:[Q("pronounce.q1","pronounce.s1","meaning","If a teacher asks you to pronounce a word, what should you do?",["Say its sounds aloud","Write its definition only","Translate it without speaking"],"Say its sounds aloud","Pronounce in this sense means produce the word's spoken sounds.","meaning"),Q("pronounce.q2","pronounce.s2","context","A judge pronounces a sentence after a trial. What is happening?",["The judge formally states the court's decision","The judge teaches how to say a name","The judge changes a word's spelling"],"The judge formally states the court's decision","This is the formal-declaration sense of pronounce.","context"),Q("pronounce.q3","pronounce.s1","grammar","Choose the natural question.",["How do you pronounce this surname?","How do you pronounce to this surname?","How do you pronounce at this surname?"],"How do you pronounce this surname?","Pronounce takes the name directly as its object.","grammar"),Q("pronounce.q4","pronounce.s2","word-choice","The panel formally declared the proposal invalid. It ____ the proposal invalid.",["pronounced","pronouncedly","pronunciation"],"pronounced","Pronounce can formally state a decision, followed by an object and complement.","word-choice")]});
D("pronounceable",{etymology:E("Formed from pronounce + -able, a suffix meaning ‘able or possible to be’; it describes a spelling or sound sequence that a speaker can say.",null,"pronounce","-able","Etymonline, pronounce (https://www.etymonline.com/word/pronounce)."),contexts:[C("pronounceable.s1","設計","The game designers gave each island a pronounceable name so children could call out destinations during play.","遊戲設計者替每座島取了容易發音的名字，讓孩子們遊玩時能大聲喊出目的地。","Pronounceable means possible or easy for a speaker to say.","Pronounceable modifies name; so introduces the practical reason for that choice.","Children can speak the names without struggling over an awkward sound sequence.")],mistakes:[M("grammar","The company chose an pronounceable name for its new app.","The company chose a pronounceable name for its new app.","Pronounceable begins with a consonant sound, so the article is a, not an.")],quiz:[Q("pronounceable.q1","pronounceable.s1","meaning","A pronounceable brand name is one that people can ___.",["say aloud","own as real estate","use as proof in geometry"],"say aloud","The adjective describes a word or name that can be spoken.","meaning"),Q("pronounceable.q2","pronounceable.s1","context","Why choose a pronounceable username for a radio contest?",["Listeners can repeat it after hearing it once.","It must be impossible to read aloud.","It guarantees the user owns a building."],"Listeners can repeat it after hearing it once.","The name should be easy enough to say and recognize.","context"),Q("pronounceable.q3","pronounceable.s1","word-formation","What does -able contribute in pronounceable?",["capable of being pronounced","already pronounced in the past","without any pronunciation"],"capable of being pronounced","The suffix -able forms an adjective meaning possible or capable of the action.","word-formation"),Q("pronounceable.q4","pronounceable.s1","grammar","Which phrase has the correct article?",["a pronounceable title","an pronounceable title","the pronounceablely title"],"a pronounceable title","Pronounceable begins with the consonant sound /p/ and takes a.","grammar")]});
D("pronounced",{etymology:E("From the past participle of pronounce, from Latin pronuntiare ‘announce, utter’; as an adjective it developed the senses ‘clearly noticeable’ and ‘stated firmly’. ","pro-","nuntiare","-ed","Etymonline, pronounce (https://www.etymonline.com/word/pronounce)."),contexts:[C("pronounced.s1","語言","Even after years abroad, his pronounced regional accent was easy to recognize on the radio.","即使在海外多年，他明顯的地方口音仍讓人在廣播中一聽就認得出來。","Pronounced can mean very noticeable or distinct.","Pronounced modifies accent; even after contrasts the long absence with the still-clear feature.","The accent remains readily audible to listeners.") ,C("pronounced.s2","社會","The candidate took a pronounced position against the proposed cuts, repeating the objection at every public meeting.","這名候選人鮮明反對擬議中的削減措施，並在每場公開會議上重申立場。","Pronounced can describe a firmly and clearly stated opinion or position.","Pronounced modifies position; against identifies the view, while the participial phrase shows its firmness.","The candidate states the opposition clearly and consistently.")],mistakes:[M("meaning","The two readings showed a pronounced difference, although every measured value and sound was exactly identical.","The two readings showed no pronounced difference, since every measured value and sound was identical.","A pronounced difference is conspicuous; identical measurements do not reveal such a difference.")],quiz:[Q("pronounced.q1","pronounced.s1","meaning","A pronounced smell is ___.",["strong or easy to notice","impossible to detect","a formal court judgment"],"strong or easy to notice","The adjective can mean distinctly noticeable to the senses.","meaning"),Q("pronounced.q2","pronounced.s2","context","A politician has pronounced views on housing. The views are ___.",["clearly and firmly stated","too quiet to identify","physically raised above a surface"],"clearly and firmly stated","This sense describes a definite, strongly expressed position.","context"),Q("pronounced.q3","pronounced.s1","word-choice","The difference between the twins' voices was so ____ that callers recognized who had answered.",["pronounced","pronounceable","pronunciation"],"pronounced","The difference was clear and easy to notice.","word-choice"),Q("pronounced.q4","pronounced.s2","confusable","Which phrase describes a clearly expressed opinion?",["a pronounced view","a pronounceable view","a pronunciation view"],"a pronounced view","Pronounced can mean expressed firmly and clearly.","confusable")]});
D("pronunciation",{etymology:E("From Old French pronunciation and Latin pronuntiationem, the action noun from pronuntiare ‘announce, utter’. The word's sound sense names the way a word or language is spoken.","pro-","nuntiare","-ation","Etymonline, pronounce (https://www.etymonline.com/word/pronounce)."),contexts:[C("pronunciation.s1","教育","The language tutor corrected the student's pronunciation of sheet, because the vowel had sounded like the one in ship.","語言家教糾正了學生對 sheet 的發音，因為他的母音聽起來像 ship 裡的母音。","Pronunciation is the way a word or language is spoken.","Pronunciation is the object of corrected; of sheet identifies the word, and because explains the correction.","The tutor distinguishes two vowel sounds that change what listeners hear.")],mistakes:[M("spelling","Her pronounciation of the French name was clear and confident.","Her pronunciation of the French name was clear and confident.","Pronunciation is spelled without the second o found in pronounce; pronounciation is a misspelling.")],quiz:[Q("pronunciation.q1","pronunciation.s1","meaning","A dictionary's pronunciation guide tells you ___.",["how a word is spoken","who owns a piece of land","whether an argument is a proof"],"how a word is spoken","Pronunciation names the spoken form of a word.","meaning"),Q("pronunciation.q2","pronunciation.s1","context","Why compare pronunciation recordings of two dialects?",["To hear differences in how speakers say words","To establish who owns the recording studio","To calculate a geometric theorem"],"To hear differences in how speakers say words","Dialect pronunciation concerns spoken sound patterns.","context"),Q("pronunciation.q3","pronunciation.s1","spelling","Which spelling is correct?",["pronunciation","pronounciation","pronuncation"],"pronunciation","The noun is pronunciation, without an extra o after n.","spelling"),Q("pronunciation.q4","pronunciation.s1","word-choice","The accent coach worked on the actor's ____ of the character's surname.",["pronunciation","propensity","property"],"pronunciation","The coach is improving how the surname is spoken.","word-choice")]});
D("proof",{etymology:E("From Anglo-French prove/preove and Old French proeve, from Late Latin proba ‘proof, test’, a back-formation from Latin probare ‘test, demonstrate’. The noun later developed printing and mathematical senses.",null,"probare",null,"Etymonline, proof (https://www.etymonline.com/word/proof)."),contexts:[C("proof.s1","通用","The camera footage provided proof that the delivery truck arrived before the gate was locked.","監視器畫面證明送貨卡車是在大門上鎖前抵達的。","Proof is evidence or a test establishing that something is true.","Proof is the object of provided; that-clause states the fact supported.","The footage is evidence for the truck's arrival time.") ,C("proof.s2","出版","The editor marked a missing comma on the final proof before the pages went to the printer.","頁面送印前，編輯在最後一份校樣上標出漏掉的逗號。","A proof is a trial printed copy checked before the final print run.","Proof is the object of marked; before establishes that correction happened pre-print.","The editor is reviewing a sample of the pages to catch errors.") ,C("proof.s3","數學","Her proof showed that the sum of two even integers must also be even by factoring out two.","她的證明透過提出公因數二，說明兩個偶整數的和必定也是偶數。","A mathematical proof is a logical argument demonstrating that a statement must be true.","Proof is the subject; that-clause names the theorem and by introduces the reasoning method.","The argument derives the claim from a general property of even integers.") ,C("proof.s4","安全","The seal is proof against rain but not against prolonged immersion in water.","這個封條能防雨，但不能防止長時間浸水。","In the phrase proof against, proof means able to resist a particular harm.","Proof follows is as a complement; against introduces the hazard resisted.","The seal resists rain exposure but has a stated limit.")],mistakes:[M("meaning","There is proof that Inez took the keys because no witness saw her, no camera recorded her, and no keys were found with her.","There is no proof that Inez took the keys because no witness saw her, no camera recorded her, and none were found with her.","The listed facts provide no evidence connecting Inez to the keys, so they cannot establish the claim.")],quiz:[Q("proof.q1","proof.s1","meaning","In “The receipt is proof of payment,” proof means ___.",["evidence that something is true","a printed trial page","a walkway by the sea"],"evidence that something is true","The receipt supports the claim that payment was made.","meaning"),Q("proof.q2","proof.s2","context","A publisher sends a proof to an author before printing. What is it?",["A trial copy of the pages for checking","A final book sold to readers","A contract giving the author a job"],"A trial copy of the pages for checking","A printing proof is inspected before the final run.","context"),Q("proof.q3","proof.s3","meaning","What makes a mathematical proof different from a guess?",["It gives a logical argument establishing the result.","It merely says the result feels likely.","It lists unrelated examples without reasoning."],"It gives a logical argument establishing the result.","A proof demonstrates a mathematical claim through valid reasoning.","meaning"),Q("proof.q4","proof.s4","collocation","A rainproof jacket is proof ____ rain.",["against","among","beside"],"against","Proof against is the standard pattern for resistance to a harm.","collocation")]});
D("proof-read",{etymology:E("A compound of proof and read, coined for checking printers' proofs; the verb is also written proofread without a hyphen. Etymonline dates proof-read/proofread to 1878 and says it was probably back-formed from proof-reader.",null,"proof + read",null,"Etymonline, proof-read (https://www.etymonline.com/word/proof-read)."),contexts:[C("proof-read.s1","出版","Please proof-read the translated captions against the source file before the museum sends them to the printer.","博物館送印前，請對照原始檔校對譯好的圖說。","To proof-read is to check a draft or proof for spelling, grammar, and printing errors.","Proof-read takes captions as its direct object; against the source file names the comparison copy.","The reviewer compares the translated text with its source before printing.")],mistakes:[M("collocation","Please proof-read to the translated captions before the museum sends them to the printer.","Please proof-read the translated captions before the museum sends them to the printer.","Proof-read is transitive here and takes the text directly; to should be removed before the object.")],quiz:[Q("proof-read.q1","proof-read.s1","meaning","When you proof-read a leaflet, you ___.",["check it for errors before publication","write its entire story from memory","announce it in court"],"check it for errors before publication","Proof-reading is a review for spelling, grammar, and typographical errors.","meaning"),Q("proof-read.q2","proof-read.s1","context","Why proof-read captions against the source file?",["To catch wording or typing errors before the captions are printed","To make the source file disappear","To prove ownership of the museum"],"To catch wording or typing errors before the captions are printed","Comparing the draft with its source helps identify mistakes.","context"),Q("proof-read.q3","proof-read.s1","spelling","Which form is also accepted in standard usage?",["proofread","proofred","prooffread"],"proofread","Proofread is the common unhyphenated spelling of the same verb.","spelling"),Q("proof-read.q4","proof-read.s1","grammar","Choose the sentence with the direct object correctly placed.",["Please proof-read the report tonight.","Please proof-read to the report tonight.","Please proof-read at the report tonight."],"Please proof-read the report tonight.","The document is the direct object of proof-read.","grammar")]});
D("proofread",{etymology:E("A compound of proof and read, the verb for checking a printer's proof or other draft; it is also written proof-read. The recorded verb was probably back-formed from proof-reader in 1878.",null,"proof + read",null,"Etymonline, proof-read (https://www.etymonline.com/word/proof-read)."),contexts:[C("proofread.s1","教育","Niko proofread his scholarship letter twice, correcting a misplaced comma before he sent it.","尼科把獎學金申請信校對了兩遍，寄出前修正了一個逗號位置錯誤。","To proofread a document is to read it to find and mark errors.","Proofread takes letter as its object; correcting explains the review, and before fixes the order.","He checks the completed letter and corrects a punctuation error before sending it.") ,C("proofread.s2","出版","She proofread manuscripts for a small press, checking each page against the author's approved copy.","她替一家小型出版社校對手稿，逐頁對照作者核准的版本檢查。","Proofread can also mean doing proofreading as a job or publishing task.","Proofread takes manuscripts as its object; for identifies the employer, while the participial phrase gives the method.","The sentence describes proofreading as her regular work.")],mistakes:[M("verb-form","Yesterday she proofreads the final chapter before sending it to the printer.","Yesterday she proofread the final chapter before sending it to the printer.","Proofread is an irregular verb whose past tense has the same spelling as its base form.")],quiz:[Q("proofread.q1","proofread.s1","meaning","What does an editor do when she proofreads a chapter?",["Reads it to find errors","Writes a mathematical theorem","Supports a window with a stick"],"Reads it to find errors","Proofreading is the process of checking written text for errors.","meaning"),Q("proofread.q2","proofread.s2","context","If Mina proofreads manuscripts for a press, what is likely true?",["She performs text checking as part of her work.","She owns every manuscript outright.","She reads only the titles aloud on stage."],"She performs text checking as part of her work.","This sense refers to doing proofreading as a job or stage of publication.","context"),Q("proofread.q3","proofread.s1","verb-form","Choose the correct past-tense sentence.",["I proofread the report last night.","I proofreaded the report last night.","I proofreads the report last night."],"I proofread the report last night.","The past tense of proofread is also proofread, without -ed.","verb-form"),Q("proofread.q4","proofread.s1","confusable","Which activity is proofreading?",["Checking a draft for typos before sending it","Predicting tomorrow's weather","Selling the printed book at a shop"],"Checking a draft for typos before sending it","Proofreading catches errors in a text before it is finalized.","confusable")]});
D("prop",{etymology:E("The support noun prop is probably from Middle Dutch proppe ‘support, stopper’, of unknown deeper origin; prop the verb derives from that support sense. A stage or film prop is a separate shortening of properties, a theatrical term for movable objects.",null,null,null,"Etymonline, prop (https://www.etymonline.com/word/prop)."),contexts:[C("prop.s1","維修","A wooden prop held the damaged porch roof while the builders replaced its cracked beam.","工人更換破裂橫梁時，一根木支柱撐住了受損的門廊屋頂。","A prop is an object placed under or against something to support it.","Prop is the subject; held the roof states its function, while while introduces the concurrent repair.","The wooden piece bears the roof's weight temporarily.") ,C("prop.s2","電影","The film's prop department built a lightweight moon rock that looked heavy on camera.","電影道具部製作了一塊輕巧的月岩道具，鏡頭上看起來卻很沉重。","A prop is an object used onstage or in a film as part of a scene.","Prop modifies department; that-clause describes the item the department built.","The fake rock is a scene object rather than a real geological specimen.") ,C("prop.s3","通用","She propped the bicycle against the brick wall before carrying the boxes indoors.","她把自行車靠在磚牆上，然後把箱子搬進屋。","As a verb, prop means support something or lean it against another object.","Propped takes the bicycle as object and against introduces the supporting surface.","The wall keeps the bicycle from falling over.")],mistakes:[M("collocation","She propped the bicycle at the brick wall before carrying the boxes indoors.","She propped the bicycle against the brick wall before carrying the boxes indoors.","The verb prop uses against for the surface something is leaned against.")],quiz:[Q("prop.q1","prop.s1","meaning","A prop under a sagging beam is used to ___.",["support the beam","advertise a movie","prove a theorem"],"support the beam","The support noun names an object bearing weight.","meaning"),Q("prop.q2","prop.s2","context","A detective's fake badge used in a film scene is a ___.",["prop","proof","property tax"],"prop","A stage or film prop is an object used in the performance.","context"),Q("prop.q3","prop.s3","collocation","Complete: “He propped the ladder ___ the wall.”",["against","to","among"],"against","Prop something against a surface is the standard construction.","collocation"),Q("prop.q4","prop.s2","confusable","A stage prop is different from a support prop because it is ___.",["an object used as part of a performance","always a load-bearing beam","a person's natural tendency"],"an object used as part of a performance","The theatrical prop sense comes from properties, the term for stage objects.","confusable")]});
D("propaganda",{etymology:E("From modern Latin propaganda, ‘things to be propagated’, from propagare ‘spread, extend’; the term was associated with the Catholic Congregation for the Propagation of the Faith. The English noun later came to mean organized persuasion, often with a critical tone.",null,"propagare","-anda","Etymonline, propaganda (https://www.etymonline.com/word/propaganda)."),contexts:[C("propaganda.s1","媒體","The report called the fabricated photographs propaganda because they were designed to shape opinion while hiding the source's role.","報告稱那些偽造照片是蠱惑性宣傳，因為它們旨在左右輿論，卻掩蓋了來源方的角色。","Propaganda is material or ideas spread to shape opinion, often by presenting only one side.","Propaganda is the complement after called; because explains the manipulative purpose and concealment.","The photographs promote a view while obscuring who created them and why.") ,C("propaganda.s2","政治","The movement distributed propaganda through short videos, posters, and a weekly newsletter to recruit supporters.","該運動透過短影片、海報和每週電子報散布宣傳，以招募支持者。","Propaganda can mean material produced by a group to win support for its aims.","Propaganda is the object of distributed; through lists channels, and to recruit gives the purpose.","The group circulates persuasive material to build backing.")],mistakes:[M("countability","The campaign printed three propagandas that each presented the same one-sided claim.","The campaign printed three pieces of propaganda that each presented the same one-sided claim.","Propaganda is normally uncountable in this meaning; count individual items as pieces of propaganda.")],quiz:[Q("propaganda.q1","propaganda.s1","meaning","Propaganda is often intended to ___.",["shape public opinion, sometimes by presenting a biased account","record a neutral measurement with no audience","support a roof beam"],"shape public opinion, sometimes by presenting a biased account","The word commonly describes persuasive material that promotes a viewpoint.","meaning"),Q("propaganda.q2","propaganda.s2","context","A group makes posters and short videos to recruit supporters. These materials may be called ___.",["propaganda","pronunciation","proofs"],"propaganda","The materials are produced to win support for the group's aims.","context"),Q("propaganda.q3","propaganda.s1","countability","Which phrase is standard?",["a piece of propaganda","a propaganda","many propagandas"],"a piece of propaganda","Propaganda is generally uncountable; use piece to count separate items.","countability"),Q("propaganda.q4","propaganda.s1","register","Why can calling a message propaganda sound critical?",["It may imply selective or manipulative persuasion.","It always means a mathematically proven fact.","It can only mean a stage object."],"It may imply selective or manipulative persuasion.","Modern use often suggests one-sided persuasion rather than neutral information.","register")]});
D("propagate",{etymology:E("From Latin propagare ‘set forward, spread, increase; multiply plants by layers’, from propago ‘offspring, that which propagates’, with pro ‘forth’ and the element -pag related to fastening or planting. The verb covers spreading ideas and reproducing plants.","pro-","-pag","-ate","Etymonline, propagate (https://www.etymonline.com/word/propaganda)."),contexts:[C("propagate.s1","傳播","False claims propagated through private chat groups before local reporters could check the original documents.","在地方記者查核原始文件前，錯誤說法已在私人聊天群組中傳開。","To propagate an idea or claim is to spread it to many people.","Propagated takes claims as object; through names the channel and before fixes the timeline.","The claims circulated widely through messaging groups.") ,C("propagate.s2","園藝","Gardeners propagate the rosemary from stem cuttings, rooting each piece in damp soil before planting it outdoors.","園丁用莖插條繁殖迷迭香，先讓每段插條在濕土中生根，再種到戶外。","To propagate a plant is to produce new plants from a parent, often by cuttings.","Propagate takes rosemary as its object; from introduces the source material.","Each cutting can grow into a new plant.")],mistakes:[M("meaning","The gardener propagated the rosemary by throwing the dry stems away and planting no seeds or cuttings.","The gardener propagated the rosemary by rooting healthy stem cuttings in damp soil.","Propagation produces new plants; discarding all plant material cannot reproduce the rosemary.")],quiz:[Q("propagate.q1","propagate.s1","meaning","A rumor propagates when it ___.",["spreads from person to person","is erased before anyone hears it","grows roots in a pot"],"spreads from person to person","The information sense means to spread an idea or claim widely.","meaning"),Q("propagate.q2","propagate.s2","context","A gardener propagates mint from cuttings by ___.",["growing new plants from pieces of a parent plant","printing a poster about mint","measuring the price of a garden"],"growing new plants from pieces of a parent plant","Plant propagation creates new plants, often from cuttings.","context"),Q("propagate.q3","propagate.s1","word-choice","The organization used radio broadcasts to ____ its safety message across the region.",["propagate","propel","prolong"],"propagate","Broadcasts spread the message to a wider audience.","word-choice"),Q("propagate.q4","propagate.s2","confusable","Which use of propagate refers to plant reproduction?",["Propagate a shrub from a cutting","Propagate a rumor online","Propagate a belief in a pamphlet"],"Propagate a shrub from a cutting","A cutting is plant material used to grow a new plant.","confusable")]});
D("propagation",{etymology:E("From Old French propagacion and Latin propagationem, the action noun from propagare ‘spread, extend, reproduce plants’. It names plant reproduction or the spread of a wave, idea, or signal.","pro-","-pag","-ation","Etymonline, propagation (https://www.etymonline.com/word/propaganda)."),contexts:[C("propagation.s1","園藝","Propagation of the native shrub was easiest from cuttings taken in early spring and kept under a clear cover.","早春剪取插條並罩上透明罩時，這種本土灌木最容易繁殖。","Propagation is the process of producing new plants from seed or cuttings, and can also mean the spread of waves or ideas.","Propagation is the subject; of the shrub names what is reproduced, and from introduces the successful method.","The gardeners make new plants from pieces of the parent shrub.")],mistakes:[M("meaning","Propagation of the shrub failed because every cutting formed roots and grew into a healthy new plant.","Propagation of the shrub succeeded because the cuttings formed roots and grew into healthy new plants.","Rooted cuttings show successful plant propagation, not failure.")],quiz:[Q("propagation.q1","propagation.s1","meaning","In horticulture, propagation is the process of ___.",["producing new plants","proofreading a seed catalog","promoting a garden club"],"producing new plants","Propagation includes growing plants from seeds or cuttings.","meaning"),Q("propagation.q2","propagation.s1","context","A radio engineer studies propagation of a signal. What is being studied?",["How the signal travels through space or a medium","How a flower is pruned","How a book is proofread"],"How the signal travels through space or a medium","Propagation can refer to the spread or travel of a wave.","context"),Q("propagation.q3","propagation.s1","word-formation","Which verb is the base of propagation?",["propagate","promote","pronounce"],"propagate","Propagation is the action noun formed from propagate.","word-formation"),Q("propagation.q4","propagation.s1","meaning","Which result demonstrates successful propagation by cuttings?",["A cutting develops roots and grows into a new plant.","A cutting dries out and is discarded.","A label is printed with the plant's name."],"A cutting develops roots and grows into a new plant.","A new plant growing from a cutting is the result of propagation.","meaning")]});
D("propel",{etymology:E("From Latin propellere ‘drive forward, push onward’, from pro ‘forward’ plus pellere ‘push, drive’. English uses the physical sense of moving something ahead and the figurative sense of driving a person toward an outcome.","pro-","pellere",null,"Etymonline, propel (https://www.etymonline.com/word/propel)."),contexts:[C("propel.s1","物理","Two small electric motors propel the research boat through shallow water without disturbing the riverbed.","兩具小型電動機推動研究船穿過淺水區，同時不擾動河床。","To propel is to push or drive an object so that it moves forward.","Propel takes the boat as object; through gives its path, and without states a constraint.","The motors supply forward motion to the boat.") ,C("propel.s2","職涯","A chance meeting with a patient mentor propelled the young engineer into a career in renewable energy.","與一位耐心導師的偶遇，推動這位年輕工程師投身再生能源領域。","Figuratively, propel means drive someone toward a result or new stage.","Propelled takes engineer as object and into introduces the resulting career direction.","The meeting motivates the engineer to enter the field.")],mistakes:[M("grammar","The small motor propelled the boat to through the shallow channel.","The small motor propelled the boat through the shallow channel.","Propel takes the moving object directly; through introduces its path, so the extra to is incorrect.")],quiz:[Q("propel.q1","propel.s1","meaning","An engine propels a boat by ___.",["driving it forward","checking its spelling","making it a public property"],"driving it forward","The physical sense is to push or drive something so it moves.","meaning"),Q("propel.q2","propel.s2","context","A scholarship propelled Lina into medical research. It ___.",["helped drive her toward that career","pushed her boat across a lake","proved a theorem false"],"helped drive her toward that career","The figurative sense means to move someone toward a new result or stage.","context"),Q("propel.q3","propel.s1","grammar","Choose the correct sentence.",["The turbine propels the vessel through the water.","The turbine propels to the vessel through the water.","The turbine propels through the vessel to water."],"The turbine propels the vessel through the water.","The vessel is the direct object of propel; through the water gives its route.","grammar"),Q("propel.q4","propel.s2","word-choice","Curiosity helped ____ the student toward a career in science.",["propel","proofread","prophesy"],"propel","Curiosity can figuratively drive someone toward a goal.","word-choice")]});
D("propellant",{etymology:E("From propel plus the agent or substance-forming ending -ant, via Latin propellere ‘drive forward’; a propellant is the material that provides force. The term also covers gas that pushes liquid out of an aerosol container.","pro-","pellere","-ant","Etymonline, propel (https://www.etymonline.com/word/propel)."),contexts:[C("propellant.s1","航太","The launch vehicle's liquid propellant burned in a controlled chamber to produce thrust during ascent.","運載火箭的液態推進劑在受控燃燒室中燃燒，在升空時產生推力。","A propellant is fuel or another substance that creates force to drive a rocket or similar vehicle.","Propellant is the subject; burned introduces its action, and to produce states the result.","The chemical reaction generates the thrust that moves the rocket.") ,C("propellant.s2","日用品","The aerosol can uses compressed air as a propellant to push the cleaning liquid through its nozzle.","這罐氣霧劑使用壓縮空氣作為噴射劑，將清潔液從噴嘴推出。","A propellant can also be gas that forces liquid out of an aerosol container.","Propellant is the object complement after uses; to push explains its function.","The gas pressure expels the liquid without being the cleaning agent itself.")],mistakes:[M("meaning","The aerosol's propellant was the cleaning liquid itself, while the compressed gas did nothing to move it out of the can.","The aerosol's compressed gas was the propellant that pushed the cleaning liquid out of the can.","In an aerosol, the propellant is the gas that expels the liquid, not necessarily the liquid product.")],quiz:[Q("propellant.q1","propellant.s1","meaning","A rocket propellant helps to ___.",["produce thrust that moves the rocket","proofread the launch plan","measure the rocket's pronunciation"],"produce thrust that moves the rocket","Rocket propellant provides the force needed for propulsion.","meaning"),Q("propellant.q2","propellant.s2","context","In an aerosol can, what does the propellant do?",["Pushes the liquid out through the nozzle","Gives the liquid its label","Prevents the container from having pressure"],"Pushes the liquid out through the nozzle","Compressed gas can act as the aerosol propellant.","context"),Q("propellant.q3","propellant.s1","word-choice","The launch vehicle carries enough ____ to reach orbit.",["propellant","prominence","prophecy"],"propellant","The vehicle needs the substance that produces thrust.","word-choice"),Q("propellant.q4","propellant.s2","confusable","Which is an aerosol propellant rather than the product being sprayed?",["Compressed gas that forces liquid through the nozzle","The fragrance dissolved in the liquid","The printed instructions on the can"],"Compressed gas that forces liquid through the nozzle","The propellant provides pressure; the sprayed liquid is the product.","confusable")]});
D("propelling",{etymology:E("The present participle of propel, from Latin propellere ‘drive forward’; used adjectivally for a force that moves something ahead. In British English, a propelling pencil is a mechanical pencil that advances its lead.","pro-","pellere","-ing","Etymonline, propel (https://www.etymonline.com/word/propel)."),contexts:[C("propelling.s1","工程","A propelling force from the electric motor kept the survey drone moving steadily into the headwind.","電動馬達產生的推進力讓測量無人機穩定地迎風前進。","Propelling describes a force that drives a vehicle or mechanism forward.","Propelling modifies force; from introduces its source and kept takes drone plus moving as its complement.","The motor supplies the forward force that counters the wind.")],mistakes:[M("word-choice","The propelling force stopped the drone completely and pushed it backward against the motor's direction.","The propelling force drove the drone forward against the headwind.","A propelling force moves something ahead; a force that stops or reverses it is not propelling it forward.")],quiz:[Q("propelling.q1","propelling.s1","meaning","A propelling force is a force that ___.",["drives something forward","makes a text easy to pronounce","predicts an event"],"drives something forward","The adjective comes from propel and describes forward-driving force.","meaning"),Q("propelling.q2","propelling.s1","context","The propelling force of a fan boat comes mainly from ___.",["air pushed backward by its fan","the paint on its hull","a printed proof of its map"],"air pushed backward by its fan","The fan creates the force that moves the craft forward.","context"),Q("propelling.q3","propelling.s1","word-form","Complete: “The ____ mechanism advances the pencil lead when clicked.”",["propelling","propel","propelledly"],"propelling","Propelling pencil is a British term for a mechanical pencil that advances its lead.","word form"),Q("propelling.q4","propelling.s1","word-choice","A motor provides the ____ force that moves the cart ahead.",["propelling","prominent","propaganda"],"propelling","The motor's force drives the cart forward.","word-choice")]});
D("propensity",{etymology:E("From propense + -ity, from Latin propensus, past participle of propendere ‘incline forward, lean toward’, built from pro ‘forward’ and pendere ‘hang, weigh’. The noun is a natural or habitual tendency.","pro-","pendere","-ity","Etymonline, propensity (https://www.etymonline.com/word/propensity)."),contexts:[C("propensity.s1","行為","His propensity for exaggerating travel stories made his friends ask for photographs before believing the details.","他有誇大旅行故事的傾向，因此朋友們會先要照片，才相信細節。","A propensity is a natural or habitual tendency to act in a particular way.","Propensity is followed by for plus a gerund; the result clause shows how others respond.","Exaggeration is a repeated behavioral tendency.") ,C("propensity.s2","消費","Her propensity for late-night online shopping became expensive once she began ordering a parcel every evening.","她深夜網購成癖後，每晚都下單，花費也愈來愈高。","Propensity can also mean a strong habitual liking that leads someone to do something often.","Propensity is followed by for plus the activity; once introduces when the repeated habit began.","Frequent online purchases show a habitual preference.")],mistakes:[M("collocation","He has a propensity at exaggerating stories whenever the group meets.","He has a propensity for exaggerating stories whenever the group meets.","Propensity commonly takes for before a noun or gerund; at is not the standard pattern here.")],quiz:[Q("propensity.q1","propensity.s1","meaning","A propensity to interrupt is a ___.",["tendency to interrupt often","formal ruling by a judge","printed trial page"],"tendency to interrupt often","Propensity names a person's tendency or disposition.","meaning"),Q("propensity.q2","propensity.s2","context","Which sentence shows a propensity as a habitual liking?",["He has a propensity for collecting old maps and buys one each week.","He dislikes maps and never looks at them.","He was ordered to read a map in court."],"He has a propensity for collecting old maps and buys one each week.","The repeated collecting shows a strong habitual preference.","context"),Q("propensity.q3","propensity.s1","collocation","Complete: “She has a propensity ___ taking on difficult projects.”",["for","at","with"],"for","Propensity for is a standard pattern before a gerund.","collocation"),Q("propensity.q4","propensity.s1","word-choice","The witness's ____ to overstate small problems worried the lawyer.",["propensity","propellant","prophecy"],"propensity","A repeated tendency to exaggerate is a propensity.","word-choice")]});
D("proper",{etymology:E("From Old French propre and Latin proprius ‘one's own, particular’; senses developed from what belongs to a thing to what is suitable, correct, or considered the thing itself.",null,"proprius",null,"Etymonline, proper (https://www.etymonline.com/word/proper)."),contexts:[C("proper.s1","禮儀","The guide reminded hikers to wear proper footwear before crossing the wet, uneven trail.","導覽員提醒健行者，在穿越濕滑不平的步道前要穿合適的鞋子。","Proper can mean suitable or appropriate for a particular situation.","Proper modifies footwear; before gives the timing, and the trail conditions explain why it is suitable.","Sturdy shoes are appropriate for a wet, uneven route.") ,C("proper.s2","語言","The catalog uses the proper spelling of each scientist's name, checked against the original papers.","目錄採用每位科學家姓名的正確拼法，並對照原始論文核查。","Proper can mean correct according to rules or facts.","Proper modifies spelling; checked against identifies how correctness was verified.","The names match their authoritative source forms.") ,C("proper.s3","地理","The bus stop lies outside the town proper, beyond the boundary marked on the municipal map.","公車站位於城鎮本身的範圍之外，超過市政地圖上標示的界線。","Proper can mean the thing itself or its central defined area, excluding surrounding places.","Town proper contrasts with outside it; beyond names the boundary.","The stop is outside the municipality's core official area.")],mistakes:[M("word-choice","The museum required proper diving boots, although the shoes were open sandals with no grip for the slippery steps.","The museum required proper diving boots with secure soles for the slippery steps.","Proper means suitable for the situation; open sandals without grip are unsuitable for slippery steps.")],quiz:[Q("proper.q1","proper.s1","meaning","Proper clothing for a winter hike is clothing that is ___.",["suitable for cold and wet conditions","chosen only because it is expensive","incorrectly spelled"],"suitable for cold and wet conditions","Proper can mean appropriate for the situation.","meaning"),Q("proper.q2","proper.s2","context","Which use means “correct according to the rules”?",["Use the proper spelling of the name.","The town proper excludes nearby villages.","Wear proper boots in the snow."],"Use the proper spelling of the name.","Here proper means correct spelling.","context"),Q("proper.q3","proper.s3","meaning","“The city proper” usually means ___.",["the city itself, excluding surrounding areas","the whole country around it","a correctly spelled city name"],"the city itself, excluding surrounding areas","Proper can identify a place's central or officially defined area.","meaning"),Q("proper.q4","proper.s1","word-choice","A ____ safety helmet is one that meets the job's requirements.",["proper","propensity","prologue"],"proper","The helmet must be suitable for the work.","word-choice")]});
D("properly",{etymology:E("Formed from proper + -ly, the regular adverb ending; proper comes through Old French from Latin proprius ‘one's own, particular’. Properly means in a correct or suitable way.",null,"proprius","-ly","Etymonline, proper (https://www.etymonline.com/word/proper)."),contexts:[C("properly.s1","工程","The mechanic tightened the wheel bolts properly and then checked each one with a calibrated wrench.","技工正確地鎖緊車輪螺栓，接著用校準過的扳手逐一檢查。","Properly means in the correct or suitable way.","Properly modifies tightened; and then marks the next step in the procedure.","The bolts are tightened according to the safe procedure.")],mistakes:[M("spelling","The latch did not properlyly close, so the gate swung open in the wind.","The latch did not properly close, so the gate swung open in the wind.","Properly already contains the adverb ending -ly; properlyly adds it twice.")],quiz:[Q("properly.q1","properly.s1","meaning","If a machine is properly installed, it is installed ___.",["in the correct way","without any instructions or care","in a public performance"],"in the correct way","Properly describes doing something correctly or suitably.","meaning"),Q("properly.q2","properly.s1","context","Which worker used a tool properly?",["She followed its safety instructions and checked the result.","She ignored the instructions and damaged the tool.","She left it unopened on a shelf."],"She followed its safety instructions and checked the result.","Following the directions is correct use.","context"),Q("properly.q3","properly.s1","word form","Which adverb is spelled correctly?",["properly","properlyly","properli"],"properly","Properly has a single -ly ending.","spelling"),Q("properly.q4","properly.s1","collocation","The door will not close ____ unless the hinge is aligned.",["properly","proper","property"],"properly","An adverb is needed to describe how the door closes.","word form")]});
D("property",{etymology:E("From Anglo-French proprete and Old French propriété, from Latin proprietas ‘nature, quality, ownership’, from proprius ‘one's own’. English senses include possessions, land and buildings, and a characteristic of a substance.",null,"proprius","-ty","Etymonline, property (https://www.etymonline.com/word/property)."),contexts:[C("property.s1","法律","The hikers returned the camera to its owner because they knew it was private property, not park equipment.","健行者把相機還給失主，因為他們知道那是私人財物，不是公園設備。","Property can mean something that belongs to someone or the state of ownership.","Property follows was as a subject complement; private contrasts with park equipment.","The camera belongs to an individual rather than the park.") ,C("property.s2","房地產","They bought a small property near the station and converted its garage into a bicycle workshop.","他們在車站附近買了一處小房產，並把車庫改成自行車工作室。","Property can mean a piece of land or a building that is owned.","Property is the object of bought; near the station locates the real estate.","The purchase is a parcel or building, not a movable personal possession.") ,C("property.s3","科學","Low thermal conductivity is a useful property of the ceramic lining inside the furnace.","低熱導率是爐內陶瓷襯層的一項實用特性。","A property can be a quality naturally belonging to a substance or thing.","Property is the complement of is; of the lining identifies what has that quality.","The sentence names an inherent material characteristic.")],mistakes:[M("countability","The ceramic has three property: low toxicity, stability, and low density.","The ceramic has three properties: low toxicity, stability, and low density.","A countable property needs the plural form properties after the numeral three.")],quiz:[Q("property.q1","property.s1","meaning","A lost phone is someone's property if it ___.",["belongs to that person","is a public law","has a low melting point"],"belongs to that person","Property can mean a possession belonging to someone.","meaning"),Q("property.q2","property.s2","context","A listing describes a house and the land around it for sale. Here property means ___.",["real estate","a scientific feature","a stage object"],"real estate","Land and buildings owned or offered for sale are property.","context"),Q("property.q3","property.s3","meaning","In materials science, hardness is a property of a metal. Property means ___.",["a characteristic or quality","a building for sale","a personal promise"],"a characteristic or quality","This scientific sense names a quality a material has.","meaning"),Q("property.q4","property.s2","confusable","Which phrase most clearly means real estate?",["a property near the station","private property in a camera case","the optical property of glass"],"a property near the station","A property near a location refers to owned land or buildings.","confusable")]});
D("prophecy",{etymology:E("From Old French profecie and Late Latin prophetia, from Greek prophēteia ‘gift of interpreting the will of the gods’, from prophētēs ‘spokesperson, prophet’. The noun names a prediction or inspired utterance.",null,"phanai",null,"Etymonline, prophecy (https://www.etymonline.com/word/prophecy)."),contexts:[C("prophecy.s1","文學","The old prophecy said the river would flood after three years without snow in the mountains.","古老的預言說，若山上連續三年沒有降雪，河流就會氾濫。","A prophecy is a prediction of a future event, often with a religious or inspired character.","Prophecy is the subject; said introduces its content, and would marks the predicted future from a past viewpoint.","The statement forecasts a future flood.")],mistakes:[M("spelling","The prophet's prophesy warned that the river would flood.","The prophet's prophecy warned that the river would flood.","Prophecy is the noun for a prediction; prophesy is the verb meaning to predict or speak prophetically.")],quiz:[Q("prophecy.q1","prophecy.s1","meaning","A prophecy is ___.",["a prediction about the future","a piece of stage equipment","a tendency to exaggerate"],"a prediction about the future","The noun names a predicted future event or inspired utterance.","meaning"),Q("prophecy.q2","prophecy.s1","context","A scroll contains a prophecy that a city will be rebuilt. The scroll contains ___.",["a prediction","a property deed","a pronunciation guide"],"a prediction","The statement foretells a future event.","context"),Q("prophecy.q3","prophecy.s1","spelling","Choose the correct noun spelling: “The ___ was written centuries ago.”",["prophecy","prophesy","prophecied"],"prophecy","The noun ends in -cy; prophesy is the verb.","spelling"),Q("prophecy.q4","prophecy.s1","word-choice","The priest recorded the ancient ____ in the temple archive.",["prophecy","propensity","propellant"],"prophecy","The archive contains a prediction, so the noun prophecy fits.","word-choice")]});
D("prophesy",{etymology:E("From Old French profeciier/prophecier, based on the noun prophecy, ultimately from Greek prophēteia and prophētēs ‘spokesperson, prophet’. The verb means to speak prophetically or foretell; its spelling differs from the noun.",null,"phanai",null,"Etymonline, prophecy (https://www.etymonline.com/word/prophecy)."),contexts:[C("prophesy.s1","宗教","The oracle prophesied a severe drought, and the villagers stored water before the dry season began.","神諭預言將有嚴重旱災，村民因此在旱季開始前儲水。","To prophesy is to say publicly what will happen in the future.","Prophesied takes drought as its object; before shows that preparation followed the prediction.","The oracle foretells a future event and people act on that forecast.")],mistakes:[M("spelling","The oracle prophecyed that the river would rise before dawn.","The oracle prophesied that the river would rise before dawn.","The verb is prophesy; its past tense is prophesied, not prophecyed.")],quiz:[Q("prophesy.q1","prophesy.s1","meaning","To prophesy is to ___.",["foretell or speak about a future event","correct a printer's proof","support a roof with a beam"],"foretell or speak about a future event","The verb means to predict or speak prophetically.","meaning"),Q("prophesy.q2","prophesy.s1","context","A historian says a writer prophesied a famine. The writer ___.",["predicted a famine","owned a farm","proofread a report"],"predicted a famine","To prophesy is to foretell a future event.","context"),Q("prophesy.q3","prophesy.s1","spelling","Which is the correct past tense of prophesy?",["prophesied","prophecyed","prophesyed"],"prophesied","The spelling changes y to i before -ed: prophesy, prophesied.","spelling"),Q("prophesy.q4","prophesy.s1","confusable","Which sentence uses the verb rather than the noun?",["The seer will prophesy about the coming storm.","The seer's prophecy described a storm.","The prophecy was written on a scroll."],"The seer will prophesy about the coming storm.","Prophesy is the verb; prophecy is the noun.","confusable")]});
})();
